source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    border_colors = {v for v in grid[0] + grid[-1]} | {grid[r][c] for r in range(h) for c in (0, w-1)}
    marker = next((v for v in border_colors if v != bg), None)
    if marker is None:
        return out
    dots = [(r,c,grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] not in (bg, marker)]
    if not dots:
        return out
    paint = dots[0][2]
    # Border bars running horizontally project their columns through the interior.
    top_cols = [c for c,v in enumerate(grid[0]) if v == marker]
    bot_cols = [c for c,v in enumerate(grid[-1]) if v == marker]
    if top_cols or bot_cols:
        cols = set(top_cols + bot_cols)
        for r in range(1, h-1):
            for c in cols:
                if grid[r][c] == bg or grid[r][c] == paint:
                    out[r][c] = paint
        for r,c,v in dots:
            out[r][c] = 4
        return out
    # Vertical border bars: dots cast horizontal rays, while a left-hand bar
    # also paints its interior rows.
    left_rows = [r for r in range(h) if grid[r][0] == marker]
    right_rows = [r for r in range(h) if grid[r][-1] == marker]
    if left_rows:
        rows_to_fill = left_rows if min(left_rows) > 0 else [0]
        for r in rows_to_fill:
            for c in range(1, w):
                if grid[r][c] == bg or grid[r][c] == paint:
                    out[r][c] = paint
    for r,c,v in dots:
        out[r][c] = 4
        if right_rows and c < w-1:
            # Extend toward the right-side marker, if one is present on this row.
            if r in right_rows:
                for cc in range(c+1, w-1):
                    if grid[r][cc] == bg:
                        out[r][cc] = paint
        # A dot to the left of an interior vertical bar emits toward that bar.
        for cc in range(c+1, w):
            if grid[r][cc] == marker:
                for k in range(c+1, cc):
                    if grid[r][k] == bg:
                        out[r][k] = paint
                break
    return out
