    if not dots:
        return out
    paint = grid[dots[0][0]][dots[0][1]]

    def runs(lines):
        result = []
        for line in lines:
            start = None
            for i, value in enumerate(line + [None]):
                if value == marker and start is None:
                    start = i
                elif value != marker and start is not None:
                    result.append(list(range(start, i)))
                    start = None
        return result

    top_runs = runs([grid[0]])
    bottom_runs = runs([grid[-1]])
    left_runs = runs([[grid[r][0] for r in range(h)]])
    right_runs = runs([[grid[r][-1] for r in range(h)]])
    horiz_len = max([len(x) for x in top_runs + bottom_runs] or [0])
    vert_len = max([len(x) for x in left_runs + right_runs] or [0])

    for r, c in dots:
        out[r][c] = 4

    if horiz_len > vert_len:
        top = {c for run in top_runs for c in run}
