            for r in range(1, stop):
                if grid[r][c] == bg:
                    out[r][c] = paint
            if not hits and grid[h-1][c] == bg:
                out[h-1][c] = marker if len(top) >= 4 and len(bottom) >= 4 else paint
        # A bottom bar projects upward only on columns containing a dot;
