                        out[r][c] = paint
            elif len(bottom) >= 4:
                for r in range(1, h-1):
                    if grid[r][c] == bg:
                        out[r][c] = paint
        return out

    left = {r for run in left_runs for r in run}
    right = {r for run in right_runs for r in run}
    def fill_row(r, lo, hi):
